module TopModule (
    input  logic        clk,
    input  logic        reset,
    input  logic [31:0] in,
    output logic [31:0] out
);
    logic [31:0] in_prev;

    always_ff @(posedge clk) begin
        if (reset) begin
            out     <= 32'h0;
            in_prev <= 32'h0;
        end else begin
            in_prev <= in;
            for (int i = 0; i < 32; i++) begin
                if (in_prev[i] && !in[i]) begin
                    out[i] <= 1'b1;
                end
            end
        end
    end
endmodule

