module tb_TopModule;
    logic        clk;
    logic        reset;
    logic [31:0] in;
    logic [31:0] out;

    TopModule uut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(out)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        in = 32'h0;
        #12;
        reset = 0;
        #10;

        // Test 1: transition 1 -> 0 on bit 0
        in = 32'h0000_0001; // in[0] = 1
        #10;
        in = 32'h0000_0000; // in[0] = 0 (1 -> 0 transition)
        #10;
        if (out[0] !== 1'b1) begin
            $display("SELFTEST FAIL: bit 0 did not capture 1->0 transition. out = %h", out);
            $finish;
        end

        // Test 2: reset clears out
        reset = 1;
        #10;
        if (out !== 32'h0) begin
            $display("SELFTEST FAIL: reset did not clear out. out = %h", out);
            $finish;
        end
        reset = 0;
        #10;

        // Test 3: multiple bits transitioning at different times
        in = 32'h0000_000F; // bits 3:0 are 1
        #10;
        in = 32'h0000_000A; // bits 3, 1 stay 1; bits 2, 0 go 0 (1->0 on 2 and 0)
        #10;
        if (out[0] !== 1'b1 || out[2] !== 1'b1 || out[1] !== 1'b0 || out[3] !== 1'b0) begin
            $display("SELFTEST FAIL: multi-bit test failed. out = %h", out);
            $finish;
        end

        // Next cycle, make bits 3 and 1 go 0
        in = 32'h0000_0000;
        #10;
        if (out[1] !== 1'b1 || out[3] !== 1'b1) begin
            $display("SELFTEST FAIL: second multi-bit transition failed. out = %h", out);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
